"""The ``stockroom`` command line.

Arguments are parsed by hand (not argparse): its prefix matching, ``-h`` and
exit codes would conflict with the specification.

Exit status: 0 worked; 1 a data file has a mistake or the request is
refused; 2 a file cannot be read or the command line is wrong.
"""

import csv
import io
import json
import os
import sys

from ._text import ORDER_ID_RE, SKU_RE, parse_date, parse_uint
from .catalog import parse_catalog
from .errors import ParseError
from .fulfil import available_on, shipped_order, shipped_quantities, status_of
from .movements import (
    Movement,
    buy_quantity,
    first_negative,
    history,
    parse_movements,
    status,
    stock_levels,
)
from .orders import order_sort_key, parse_orders
from .pricing import money, price_order

USAGE = """\
usage: stockroom [--dir DIR] COMMAND [ARGS]

shelves:
  stock [--json]                       what is on the shelves
  low [--json]                         what needs buying
  history SKU [--json]                 movements of one product
  receive DATE SKU QUANTITY [NOTE]     add stock in
  ship DATE SKU QUANTITY [NOTE]        add stock out

orders:
  quote ORDER [--json]                 price an order
  fulfil ORDER DATE                    ship what the shelves can cover
  invoice ORDER [--json]               price what has shipped
  report [--format text|csv|json]      one row per order

--dir DIR (anywhere on the line) names the folder holding catalog.txt,
movements.txt and orders.txt; the default is the current folder.
"""

MOVEMENTS = "movements.txt"
CATALOG = "catalog.txt"
ORDERS = "orders.txt"

# command -> (min positional args, max positional args)
ARGC = {
    "stock": (0, 0),
    "low": (0, 0),
    "history": (1, 1),
    "receive": (3, 4),
    "ship": (3, 4),
    "quote": (1, 1),
    "fulfil": (2, 2),
    "invoice": (1, 1),
    "report": (0, 0),
}
JSON_COMMANDS = {"stock", "low", "history", "quote", "invoice"}
# these take no options but --dir: every other argument is taken as typed
POSITIONAL_ONLY = {"receive", "ship", "fulfil"}
# commands with a DATE argument, and its position
DATE_ARGUMENT = {"receive": 0, "ship": 0, "fulfil": 1}
FORMATS = ("text", "csv", "json")


class CliError(Exception):
    """A failure to report on stderr: exit ``status`` with ``message``."""

    def __init__(self, status, message, file=None, line=None, usage=False):
        super().__init__(message)
        self.status = status
        self.message = message
        self.file = file
        self.line = line
        self.usage = usage

    def render(self):
        if self.file and self.line is not None:
            text = "stockroom: %s: line %d: %s" % (self.file, self.line, self.message)
        elif self.file:
            text = "stockroom: %s: %s" % (self.file, self.message)
        else:
            text = "stockroom: %s" % self.message
        if self.usage:
            text += "\nusage: stockroom [--dir DIR] COMMAND [ARGS] (see --help)"
        return text + "\n"


def usage_error(message):
    return CliError(2, message, usage=True)


class Invocation:
    def __init__(self, command, args, directory, as_json=False, fmt="text"):
        self.command = command
        self.args = args
        self.directory = directory
        self.as_json = as_json
        self.format = fmt


# ----------------------------------------------------------------- parsing


def parse_command_line(argv):
    """Return an :class:`Invocation`, ``None`` for ``--help``; or raise a
    usage error (exit 2)."""
    directory = "."
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise usage_error("option --dir needs a value")
            directory = argv[i + 1]
            i += 2
        elif arg.startswith("--dir="):
            directory = arg[len("--dir="):]
            i += 1
        else:
            rest.append(arg)
            i += 1
    if not rest:
        raise usage_error("no command given")
    command = rest[0]
    if "--help" in rest and command not in POSITIONAL_ONLY:
        return None
    if command not in ARGC:
        raise usage_error("unknown command %r" % command)
    args = rest[1:]
    as_json = False
    fmt = "text"
    if command not in POSITIONAL_ONLY:
        positional = []
        i = 0
        while i < len(args):
            arg = args[i]
            i += 1
            if arg == "--json" and command in JSON_COMMANDS:
                as_json = True
            elif command == "report" and (arg == "--format" or arg.startswith("--format=")):
                if arg == "--format":
                    if i >= len(args):
                        raise usage_error("option --format needs a value")
                    fmt = args[i]
                    i += 1
                else:
                    fmt = arg[len("--format="):]
                if fmt not in FORMATS:
                    raise usage_error(
                        "bad --format value %r (text, csv or json)" % fmt
                    )
            elif arg.startswith("-") and arg != "-":
                raise usage_error("unknown option %r" % arg)
            else:
                positional.append(arg)
        args = positional
    low, high = ARGC[command]
    if not low <= len(args) <= high:
        raise usage_error("wrong number of arguments for %s" % command)
    if command in DATE_ARGUMENT:
        date_text = args[DATE_ARGUMENT[command]]
        if parse_date(date_text) is None:
            raise usage_error("bad date %r (expected a real YYYY-MM-DD)" % date_text)
    return Invocation(command, args, directory, as_json, fmt)


# ------------------------------------------------------------ file reading


def read_file(directory, name, required):
    """Text of ``directory/name``. A missing optional file reads as empty."""
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise CliError(2, "cannot read file: no such file", file=name)
        return ""
    except OSError as error:
        raise CliError(2, "cannot read file: %s" % (error.strerror or error), file=name)
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise CliError(2, "file is not valid UTF-8", file=name)


def parsed(name, function, *args):
    try:
        return function(*args)
    except ParseError as error:
        raise CliError(1, error.reason, file=name, line=error.line)


class Shop:
    """The files a command needs, read and parsed (catalogue first)."""

    def __init__(self, texts):
        self.catalog = parsed(CATALOG, parse_catalog, texts[CATALOG])
        self.movements = None
        self.orders = None
        if MOVEMENTS in texts:
            self.movements = parsed(
                MOVEMENTS, parse_movements, texts[MOVEMENTS], self.catalog
            )
        if ORDERS in texts:
            self.orders = parsed(ORDERS, parse_orders, texts[ORDERS], self.catalog)


def load_texts(directory, names):
    if not os.path.isdir(directory):
        raise CliError(2, "cannot read folder %r: no such folder" % directory)
    texts = {}
    for name in names:
        texts[name] = read_file(directory, name, required=name == CATALOG)
    return texts


FILES_NEEDED = {
    "stock": (CATALOG, MOVEMENTS),
    "low": (CATALOG, MOVEMENTS),
    "history": (CATALOG, MOVEMENTS),
    "receive": (CATALOG, MOVEMENTS),
    "ship": (CATALOG, MOVEMENTS),
    "quote": (CATALOG, ORDERS),
    "fulfil": (CATALOG, MOVEMENTS, ORDERS),
    "invoice": (CATALOG, MOVEMENTS, ORDERS),
    "report": (CATALOG, MOVEMENTS, ORDERS),
}


# ---------------------------------------------------------------- helpers


def find_sku(catalog, text):
    """The catalogue key for a command-line SKU (any case), else refuse."""
    if SKU_RE.fullmatch(text) and text.upper() in catalog:
        return text.upper()
    raise CliError(1, "unknown SKU %r" % text)


def find_order(orders, text):
    """The order for a command-line order number (any case), else refuse."""
    if ORDER_ID_RE.fullmatch(text):
        wanted = text.upper()
        for order in orders:
            if order.id == wanted:
                return order
    raise CliError(1, "unknown order %r" % text)


def dump_json(value):
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def signed(quantity):
    return "%+d" % quantity


def movement_line(date, sku, quantity, note):
    text = "%s %s %s" % (date, sku, signed(quantity))
    return text + " " + note if note else text


def append_lines(directory, name, lines):
    """Append lines to a file (binary append), adding a missing final newline."""
    path = os.path.join(directory, name)
    prefix = b""
    try:
        if os.path.getsize(path) > 0:
            with open(path, "rb") as handle:
                handle.seek(-1, os.SEEK_END)
                if handle.read(1) != b"\n":
                    prefix = b"\n"
    except FileNotFoundError:
        pass
    except OSError as error:
        raise CliError(2, "cannot write file: %s" % (error.strerror or error), file=name)
    payload = prefix + "".join(line + "\n" for line in lines).encode("utf-8")
    try:
        with open(path, "ab") as handle:
            handle.write(payload)
    except OSError as error:
        raise CliError(2, "cannot write file: %s" % (error.strerror or error), file=name)


# --------------------------------------------------------------- commands


def cmd_stock(inv, shop):
    levels = stock_levels(shop.catalog, shop.movements)
    rows = []
    for sku, onhand in levels.items():
        product = shop.catalog[sku]
        rows.append((sku, product.name, onhand, status(onhand, product.reorder)))
    if inv.as_json:
        return dump_json(
            [
                {"sku": sku, "name": name, "onhand": onhand, "status": state}
                for sku, name, onhand, state in rows
            ]
        )
    return "".join("%s %d %s %s\n" % (s, o, st, n) for s, n, o, st in rows)


def cmd_low(inv, shop):
    levels = stock_levels(shop.catalog, shop.movements)
    rows = []
    for sku, onhand in levels.items():
        reorder = shop.catalog[sku].reorder
        if status(onhand, reorder) != "ok":
            rows.append((sku, onhand, reorder, buy_quantity(onhand, reorder)))
    if inv.as_json:
        return dump_json(
            [
                {"sku": s, "onhand": o, "reorder": r, "buy": b}
                for s, o, r, b in rows
            ]
        )
    return "".join("%s %d %d %d\n" % row for row in rows)


def cmd_history(inv, shop):
    sku = find_sku(shop.catalog, inv.args[0])
    rows = history(shop.movements, sku)
    if inv.as_json:
        return dump_json(
            [
                {
                    "date": str(m.date),
                    "delta": signed(m.quantity),
                    "balance": balance,
                    "note": m.note,
                }
                for m, balance in rows
            ]
        )
    out = []
    for move, balance in rows:
        line = "%s %s %d" % (move.date, signed(move.quantity), balance)
        out.append(line + " " + move.note if move.note else line)
    return "".join(line + "\n" for line in out)


def cmd_receive_ship(inv, shop):
    date_text, sku_text, qty_text = inv.args[:3]
    note = inv.args[3].strip(" \t") if len(inv.args) == 4 else ""
    sku = find_sku(shop.catalog, sku_text)
    quantity = parse_uint(qty_text)
    if quantity is None or quantity < 1:
        raise CliError(
            1, "bad quantity %r (a whole number of one or more, no sign)" % qty_text
        )
    if "\n" in note or note.endswith("\r"):
        raise CliError(1, "a note may not contain a line break")
    try:
        note.encode("utf-8")
    except UnicodeEncodeError:
        raise CliError(1, "the note is not valid text")
    delta = quantity if inv.command == "receive" else -quantity
    move = Movement(parse_date(date_text), sku, delta, note)
    if first_negative(shop.movements + [move]) is not None:
        raise CliError(
            1, "stock of %s would go below zero on %s" % (sku, move.date)
        )
    line = movement_line(date_text, sku, delta, note)
    return "%s\n" % line, [(MOVEMENTS, [line])]


def quote_text(quote, prefix=""):
    out = ["%s%s %s %s" % (prefix, quote.order, quote.date, quote.customer)]
    for line in quote.lines:
        out.append(
            "%s %d %s %s %s %s"
            % (line.sku, line.quantity, line.unit, line.gross, line.discount, line.net)
        )
    out.append("subtotal %s" % quote.subtotal)
    out.append("order discount %s" % quote.order_discount)
    out.append("tax %s" % quote.tax)
    out.append("total %s" % quote.total)
    return "".join(line + "\n" for line in out)


def quote_json(quote):
    return {
        "order": quote.order,
        "date": str(quote.date),
        "customer": quote.customer,
        "lines": [
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit": str(line.unit),
                "gross": str(line.gross),
                "discount": str(line.discount),
                "net": str(line.net),
            }
            for line in quote.lines
        ],
        "subtotal": str(quote.subtotal),
        "order_discount": str(quote.order_discount),
        "tax": str(quote.tax),
        "total": str(quote.total),
    }


def cmd_quote(inv, shop):
    order = find_order(shop.orders, inv.args[0])
    quote = price_order(order, shop.catalog)
    if inv.as_json:
        return dump_json(quote_json(quote))
    return quote_text(quote)


def cmd_invoice(inv, shop):
    order = find_order(shop.orders, inv.args[0])
    shipped = shipped_quantities(order, shop.movements)
    billed = shipped_order(order, shipped)
    if not billed.lines:
        raise CliError(1, "nothing has shipped for order %s" % order.id)
    quote = price_order(billed, shop.catalog)
    if inv.as_json:
        return dump_json(quote_json(quote))
    return quote_text(quote, prefix="invoice ")


def cmd_fulfil(inv, shop):
    order = find_order(shop.orders, inv.args[0])
    day = parse_date(inv.args[1])
    if day < order.date:
        raise CliError(
            1, "cannot ship order %s on %s: it was ordered on %s" % (order.id, day, order.date)
        )
    before = shipped_quantities(order, shop.movements)
    out = []
    appended = []
    ordered = []
    after = []
    for sku, quantity in order.lines:
        owed = quantity - before[sku]
        ship = min(owed, available_on(shop.movements, sku, day))
        if ship > 0:
            appended.append("%s %s %s order %s" % (day, sku, signed(-ship), order.id))
        out.append("%s shipped %d backordered %d\n" % (sku, ship, owed - ship))
        ordered.append(quantity)
        after.append(before[sku] + ship)
    out.append("status %s\n" % status_of(ordered, after))
    writes = [(MOVEMENTS, appended)] if appended else []
    return "".join(out), writes


REPORT_COLUMNS = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]


def report_rows(shop):
    rows = []
    for order in sorted(shop.orders, key=order_sort_key):
        shipped = shipped_quantities(order, shop.movements)
        billed = shipped_order(order, shipped)
        ordered = [quantity for _, quantity in order.lines]
        done = [shipped[sku] for sku, _ in order.lines]
        quoted = price_order(order, shop.catalog).total
        invoiced = price_order(billed, shop.catalog).total if billed.lines else money(0)
        rows.append(
            {
                "order": order.id,
                "date": str(order.date),
                "customer": order.customer,
                "status": status_of(ordered, done),
                "ordered": sum(ordered),
                "shipped": sum(done),
                "quoted": str(quoted),
                "invoiced": str(invoiced),
            }
        )
    return rows


def cmd_report(inv, shop):
    rows = report_rows(shop)
    if inv.format == "json":
        return dump_json(rows)
    if inv.format == "csv":
        buffer = io.StringIO(newline="")
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(REPORT_COLUMNS)
        for row in rows:
            writer.writerow([row[column] for column in REPORT_COLUMNS])
        return buffer.getvalue()
    return "".join(
        "%s %s %s %s %d/%d %s %s\n"
        % (r["order"], r["date"], r["customer"], r["status"], r["shipped"],
           r["ordered"], r["quoted"], r["invoiced"])
        for r in rows
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_receive_ship,
    "ship": cmd_receive_ship,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


def run(inv):
    """Carry out a command: ``(stdout_text, [(file, lines_to_append)])``.
    Reads the files it needs; writes nothing."""
    texts = load_texts(inv.directory, FILES_NEEDED[inv.command])
    shop = Shop(texts)
    result = HANDLERS[inv.command](inv, shop)
    if isinstance(result, str):
        return result, []
    return result


# ------------------------------------------------------------------- main


def _write(stream, text):
    if stream is None:  # closed on purpose, as in ``stockroom stock >&-``
        return
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        stream.flush()
        buffer.write(text.encode("utf-8", "replace"))
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _silence_stdout():
    """After a broken pipe: point stdout at devnull so the interpreter's own
    flush at exit stays quiet."""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    try:
        inv = parse_command_line(list(argv))
        if inv is None:
            out, appends = USAGE, []
        else:
            out, appends = run(inv)
            for name, lines in appends:
                append_lines(inv.directory, name, lines)
    except CliError as error:
        try:
            _write(sys.stderr, error.render())
        except (OSError, ValueError):
            pass
        return error.status
    try:
        _write(sys.stdout, out)
    except BrokenPipeError:
        _silence_stdout()
    return 0

