    "stock": (0, 0),
    "low": (0, 0),
    "history": (1, 1),
    "receive": (3, 4),
    "ship": (3, 4),
    "quote": (1, 1),
    "fulfil": (2, 2),
    "invoice": (1, 1),
    "report": (0, 0),
}
