"""The ``stockroom`` command line.

Arguments are parsed by hand (not argparse): its prefix matching, ``-h`` and
exit codes would conflict with the specification.

Exit status: 0 worked; 1 a data file has a mistake or the request is
refused; 2 a file cannot be read or the command line is wrong.
"""

import csv
import io
import json
import os
import sys

from ._text import ORDER_ID_RE, SKU_RE, parse_date, parse_uint
from .catalog import parse_catalog
from .errors import ParseError
from .fulfil import available_on, shipped_order, shipped_quantities, status_of
from .movements import (
    Movement,
    buy_quantity,
    first_negative,
    history,
    parse_movements,
    status,
    stock_levels,
)
from .orders import order_sort_key, parse_orders
from .pricing import money, price_order

USAGE = """\
usage: stockroom [--dir DIR] COMMAND [ARGS]

shelves:
  stock [--json]                       what is on the shelves
  low [--json]                         what needs buying
  history SKU [--json]                 movements of one product
  receive DATE SKU QUANTITY [NOTE]     add stock in
  ship DATE SKU QUANTITY [NOTE]        add stock out

orders:
  quote ORDER [--json]                 price an order
  fulfil ORDER DATE                    ship what the shelves can cover
  invoice ORDER [--json]               price what has shipped
  report [--format text|csv|json]      one row per order

--dir DIR (anywhere on the line) names the folder holding catalog.txt,
movements.txt and orders.txt; the default is the current folder.
"""

MOVEMENTS = "movements.txt"
CATALOG = "catalog.txt"
ORDERS = "orders.txt"

# command -> (min positional args, max positional args)
ARGC = {
    "stock": (0, 0),
    "low": (0, 0),
    "history": (1, 1),
    "receive": (3, 4),
    "ship": (3, 4),
    "quote": (1, 1),
    "fulfil": (2, 2),
    "invoice": (1, 1),
    "report": (0, 0),
}
JSON_COMMANDS = {"stock", "low", "history", "quote", "invoice"}
# these take no options but --dir: every other argument is taken as typed
POSITIONAL_ONLY = {"receive", "ship", "fulfil"}
# commands with a DATE argument, and its position
DATE_ARGUMENT = {"receive": 0, "ship": 0, "fulfil": 1}
FORMATS = ("text", "csv", "json")


class CliError(Exception):
    """A failure to report on stderr: exit ``status`` with ``message``."""

    def __init__(self, status, message, file=None, line=None, usage=False):
        super().__init__(message)
        self.status = status
        self.message = message
        self.file = file
        self.line = line
        self.usage = usage

    def render(self):
        if self.file and self.line is not None:
            text = "stockroom: %s: line %d: %s" % (self.file, self.line, self.message)
        elif self.file:
            text = "stockroom: %s: %s" % (self.file, self.message)
        else:
            text = "stockroom: %s" % self.message
        if self.usage:
            text += "\nusage: stockroom [--dir DIR] COMMAND [ARGS] (see --help)"
        return text + "\n"


def usage_error(message):
    return CliError(2, message, usage=True)


class Invocation:
    def __init__(self, command, args, directory, as_json=False, fmt="text"):
        self.command = command
        self.args = args
        self.directory = directory
        self.as_json = as_json
        self.format = fmt


# ----------------------------------------------------------------- parsing


def parse_command_line(argv):
    """Return an :class:`Invocation`, ``None`` for ``--help``; or raise a
    usage error (exit 2)."""
    directory = "."
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise usage_error("option --dir needs a value")
            directory = argv[i + 1]
            i += 2
        elif arg.startswith("--dir="):
            directory = arg[len("--dir="):]
            i += 1
        else:
            rest.append(arg)
            i += 1
    if not rest:
        raise usage_error("no command given")
    command = rest[0]
    if "--help" in rest and command not in POSITIONAL_ONLY:
        return None
    if command not in ARGC:
        raise usage_error("unknown command %r" % command)
    args = rest[1:]
    as_json = False
    fmt = "text"
    if command not in POSITIONAL_ONLY:
        positional = []
        i = 0
        while i < len(args):
            arg = args[i]
            i += 1
            if arg == "--json" and command in JSON_COMMANDS:
                as_json = True
            elif command == "report" and (arg == "--format" or arg.startswith("--format=")):
                if arg == "--format":
                    if i >= len(args):
                        raise usage_error("option --format needs a value")
                    fmt = args[i]
                    i += 1
                else:
                    fmt = arg[len("--format="):]
                if fmt not in FORMATS:
                    raise usage_error(
                        "bad --format value %r (text, csv or json)" % fmt
                    )
            elif arg.startswith("-") and arg != "-":
                raise usage_error("unknown option %r" % arg)
            else:
                positional.append(arg)
        args = positional
    low, high = ARGC[command]
    if not low <= len(args) <= high:
        raise usage_error("wrong number of arguments for %s" % command)
    if command in DATE_ARGUMENT:
        date_text = args[DATE_ARGUMENT[command]]
        if parse_date(date_text) is None:
            raise usage_error("bad date %r (expected a real YYYY-MM-DD)" % date_text)
    return Invocation(command, args, directory, as_json, fmt)


# ------------------------------------------------------------ file reading


def read_file(directory, name, required):
    """Text of ``directory/name``. A missing optional file reads as empty."""
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise CliError(2, "cannot read file: no such file", file=name)
        return ""
    except OSError as error:
        raise CliError(2, "cannot read file: %s" % (error.strerror or error), file=name)
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise CliError(2, "file is not valid UTF-8", file=name)


def parsed(name, function, *args):
    try:
        return function(*args)
    except ParseError as error:
        raise CliError(1, error.reason, file=name, line=error.line)


class Shop:
    """The files a command needs, read and parsed (catalogue first)."""

    def __init__(self, texts):
        self.catalog = parsed(CATALOG, parse_catalog, texts[CATALOG])
        self.movements = None
        self.orders = None
        if MOVEMENTS in texts:
            self.movements = parsed(
                MOVEMENTS, parse_movements, texts[MOVEMENTS], self.catalog
            )
        if ORDERS in texts:
            self.orders = parsed(ORDERS, parse_orders, texts[ORDERS], self.catalog)


def load_texts(directory, names):
    if not os.path.isdir(directory):
        raise CliError(2, "cannot read folder %r: no such folder" % directory)
    texts = {}
    for name in names:
        texts[name] = read_file(directory, name, required=name == CATALOG)
    return texts


FILES_NEEDED = {
    "stock": (CATALOG, MOVEMENTS),
    "low": (CATALOG, MOVEMENTS),
    "history": (CATALOG, MOVEMENTS),
    "receive": (CATALOG, MOVEMENTS),
    "ship": (CATALOG, MOVEMENTS),
    "quote": (CATALOG, ORDERS),
    "fulfil": (CATALOG, MOVEMENTS, ORDERS),
    "invoice": (CATALOG, MOVEMENTS, ORDERS),
    "report": (CATALOG, MOVEMENTS, ORDERS),
