        result = self.run_cli("stock", "--json")
        self.assertOk(result)
        self.assertIn('"onhand": %s,' % DOUBLE, result.out)

    def test_history(self):
        result = self.run_cli("history", "AB-100")
        self.assertOk(result)
        self.assertTrue(result.out.endswith("+%s %s\n" % (NINES, DOUBLE)))

    def test_history_json(self):
        result = self.run_cli("history", "AB-100", "--json")
        self.assertOk(result)
        self.assertIn('"balance": %s,' % DOUBLE, result.out)

    def test_receive_leaves_folder_usable(self):
        self.assertOk(self.run_cli("receive", "2024-01-03", "AB-100", NINES))
        self.assertOk(self.run_cli("stock"))
        self.assertOk(self.run_cli("low"), "")

    def test_limit_put_back_in_process(self):
        before = sys.get_int_max_str_digits()
        main(["--dir", self.dir, "stock"])
        self.assertEqual(sys.get_int_max_str_digits(), before)


