        buy = digits(2 * int(NINES))
        self.assertOk(self.run_cli("low"), "AB-100 0 %s %s\n" % (NINES, buy))

    def test_low_json(self):
        result = self.run_cli("low", "--json")
        self.assertOk(result)
        self.assertIn('"reorder": %s,' % NINES, result.out)


