        result = self.run_cli("quote", "SO-1")
        self.assertOk(result)
        self.assertIn("\ntotal ", result.out)

    def test_quote_json(self):
        self.assertOk(self.run_cli("quote", "SO-1", "--json"))

    def test_fulfil_invoice_report(self):
        self.assertOk(self.run_cli("fulfil", "SO-1", "2024-01-02"))
        self.assertOk(self.run_cli("invoice", "SO-1"))
        self.assertOk(self.run_cli("invoice", "SO-1", "--json"))
        for fmt in ("text", "csv", "json"):
            self.assertOk(self.run_cli("report", "--format", fmt))


