        )


class Library(unittest.TestCase):
    def test_money_past_limit(self):
        value = pricing.money(10 ** 5000 + 7)
        self.assertEqual(str(value), "1" + "0" * 4998 + "0.07")

    def test_money_negative_past_limit(self):
        self.assertEqual(str(pricing.money(-(10 ** 5000))), "-1" + "0" * 4998 + "0.00")

    def test_int_text(self):
        self.assertEqual(int_text(10 ** 5000), "1" + "0" * 5000)

    def test_parse_uint_cap(self):
        self.assertIsNone(parse_uint("9" * 4301))
        self.assertEqual(parse_uint("9" * 4300), int("9" * 4300))

    def test_parse_uint_cap_when_limit_lifted(self):
        if not HAS_LIMIT:
            self.skipTest("no digit limit")
        old = sys.get_int_max_str_digits()
        sys.set_int_max_str_digits(0)
        try:
            self.assertIsNone(parse_uint("9" * 4301))
        finally:
            sys.set_int_max_str_digits(old)


if __name__ == "__main__":
    unittest.main()
